import { presentBatch } from "./batch-presenter.js";

export function createFeedPanel({ history, paintRows, showCount }) {
  let currentVisit = null;

  const retireCurrentVisit = () => {
    const visit = currentVisit;
    currentVisit = null;
    if (visit) visit.release();
  };

  return {
    show(feed, mode = "synchronous") {
      retireCurrentVisit();

      const visit = { release: () => {} };
      currentVisit = visit;
      const release = subscribeFeed(feed, mode, frame => {
        if (currentVisit !== visit) return;
        presentBatch(frame, {
          paintRows,
          showCount,
          isCurrent: () => currentVisit === visit,
        });
      }, history);

      // Startup can synchronously render, and rendering can navigate or hide.
      // Do not publish this visit's cleanup after such a reentrant retirement.
      if (currentVisit === visit) visit.release = release;
      else release();
    },
    close() {
      retireCurrentVisit();
    },
  };
}

